import{_ as d,C as i,o as l,c as h,a6 as r,E as a,j as t,a as s}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"HTTP Host Header Attacks","description":"Host routing, password-reset poisoning, cache poisoning, routing SSRF, absolute-URI parsing, and dangling markup.","frontmatter":{"title":"HTTP Host Header Attacks","description":"Host routing, password-reset poisoning, cache poisoning, routing SSRF, absolute-URI parsing, and dangling markup."},"headers":[],"relativePath":"host-header/index.md","filePath":"host-header/index.md"}'),c={name:"host-header/index.md"};function u(p,e,g,m,b,k){const o=i("LabGroup"),n=i("TopicComplete");return l(),h("div",null,[e[0]||(e[0]=r('<h1 id="http-host-header-attacks" tabindex="-1">HTTP Host Header Attacks <a class="header-anchor" href="#http-host-header-attacks" aria-label="Permalink to &quot;HTTP Host Header Attacks&quot;">​</a></h1><p class="wd-section-lede">The <code>Host</code> header tells a shared server which site the client wants. Applications also use it to build absolute URLs, route requests, and make access decisions. Every one of those uses is a trust decision about a client-controlled string.</p><div class="wd-callout"><p><strong>The model.</strong> A reverse proxy routes by <code>Host</code>; the application may generate links with it, compare it to an allow-list, or pass it to an internal request. If any of those paths treats the header as authoritative without validation, the attacker can redirect, poison, or reach internal services.</p></div><h2 id="where-the-host-header-is-used" tabindex="-1">Where the Host header is used <a class="header-anchor" href="#where-the-host-header-is-used" aria-label="Permalink to &quot;Where the Host header is used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Use</th><th>Attack</th></tr></thead><tbody><tr><td>Build absolute URLs in email</td><td>password-reset poisoning</td></tr><tr><td>Route to a virtual host</td><td>admin interface access</td></tr><tr><td>Cache key or cache variation</td><td>cache poisoning</td></tr><tr><td>Internal service discovery</td><td>SSRF / routing-based SSRF</td></tr><tr><td>Access-control decision</td><td><code>Host: localhost</code> bypass</td></tr></tbody></table>',5)),a(o,{ids:"host-header-lab-host-header-basic-password-reset-poisoning, host-header-lab-host-header-authentication-bypass"}),e[1]||(e[1]=r(`<details class="details custom-block"><summary>🔬 Under the Hood: absolute-form request targets</summary><p>An HTTP/1.1 request line can be:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /path HTTP/1.1          → origin-form</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http://host/path HTTP/1.1 → absolute-form</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Proxies must accept absolute-form. If the proxy routes on the absolute URI&#39;s host but the backend routes on the <code>Host</code> header (or vice versa), the attacker can make each layer see a different destination. This is the basis of routing-based SSRF and some access-control bypasses.</p><p>The <code>Host</code> header is also allowed to contain a port, IPv6 brackets, and a trailing dot. Validators that compare strings rather than parsing the authority component are trivially bypassed.</p></details><h2 id="password-reset-poisoning" tabindex="-1">Password reset poisoning <a class="header-anchor" href="#password-reset-poisoning" aria-label="Permalink to &quot;Password reset poisoning&quot;">​</a></h2><p>The reset email contains a link built from <code>Host</code> (or <code>X-Forwarded-Host</code>). Point it at your server, request a reset for the victim, and the victim clicks a link containing their token on your domain.</p>`,3)),a(o,{ids:"host-header-lab-host-header-password-reset-poisoning-via-dangling-markup"}),e[2]||(e[2]=t("p",null,"The dangling-markup variant uses an unterminated attribute to capture the token from the email body, which is useful when the link itself is not fully attacker-controlled.",-1)),e[3]||(e[3]=t("h2",{id:"cache-poisoning-via-ambiguous-requests",tabindex:"-1"},[s("Cache poisoning via ambiguous requests "),t("a",{class:"header-anchor",href:"#cache-poisoning-via-ambiguous-requests","aria-label":'Permalink to "Cache poisoning via ambiguous requests"'},"​")],-1)),e[4]||(e[4]=t("p",null,[s("If the cache keys on one host representation and the origin renders another, a request with a crafted "),t("code",null,"Host"),s(" can poison a shared cache entry.")],-1)),a(o,{ids:"host-header-lab-host-header-web-cache-poisoning-via-ambiguous-requests"}),e[5]||(e[5]=t("h2",{id:"routing-based-ssrf",tabindex:"-1"},[s("Routing-based SSRF "),t("a",{class:"header-anchor",href:"#routing-based-ssrf","aria-label":'Permalink to "Routing-based SSRF"'},"​")],-1)),e[6]||(e[6]=t("p",null,[s("When the proxy routes by "),t("code",null,"Host"),s(", setting it to an internal hostname makes the proxy send the request to an internal service. This is SSRF without a URL parameter.")],-1)),a(o,{ids:"host-header-lab-host-header-routing-based-ssrf, host-header-lab-host-header-ssrf-via-flawed-request-parsing"}),e[7]||(e[7]=t("h2",{id:"connection-state-attacks",tabindex:"-1"},[s("Connection-state attacks "),t("a",{class:"header-anchor",href:"#connection-state-attacks","aria-label":'Permalink to "Connection-state attacks"'},"​")],-1)),e[8]||(e[8]=t("p",null,[s("Some front ends validate the "),t("code",null,"Host"),s(" on the first request of a connection and reuse the routing decision for later requests. Sending a valid request first and an invalid "),t("code",null,"Host"),s(" second can bypass the check.")],-1)),a(o,{ids:"host-header-lab-host-header-host-validation-bypass-via-connection-state-attack"}),e[9]||(e[9]=r('<details class="details custom-block"><summary>⚙️ Engine Variations: host parsing</summary><ul><li><strong>Nginx</strong> <code>server_name</code> matching includes wildcards and regex; <code>$host</code> uses the request line or Host header depending on config.</li><li><strong>Apache</strong> <code>VirtualHost</code> matching is case-insensitive; <code>UseCanonicalName</code> changes self-referential URLs.</li><li><strong>Node</strong> <code>req.headers.host</code> is raw; <code>new URL()</code> normalises it.</li><li><strong>Java</strong> <code>HttpServletRequest.getServerName()</code> may return the Host header or the connector&#39;s configured name.</li><li><strong>Cloud load balancers</strong> may rewrite <code>Host</code> or preserve it; <code>X-Forwarded-Host</code> is a separate, equally spoofable input.</li></ul><p>The mismatch between &quot;the host used for routing&quot; and &quot;the host used for URL generation&quot; is the vulnerability.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Configure a canonical host and reject requests whose <code>Host</code> is not on an exact allow-list. Build absolute URLs from configuration, never from request headers. Do not trust <code>X-Forwarded-Host</code> unless a trusted proxy sets and strips it. Route on the same parsed authority that you validate. Disable unused virtual hosts.</p></div>',2)),a(n,{"topic-id":"http-host-header-attacks",label:"Mark Host header attacks complete"})])}const y=d(c,[["render",u]]);export{v as __pageData,y as default};
